 ('upstream_functions_exact',not exists(select 1 from function_differences)),('vat_incomplete_not_invented',not exists(select 1 from finance_tax_periods where input_vat_status<>'incomplete' or input_vat_amount is not null or net_vat_amount is not null)),
 ('only_confirmed_outgoing_evidence',not exists(select 1 from finance_outgoing_wht_obligations w left join finance_payouts p on p.id=w.payout_source_id where p.status is distinct from 'confirmed')),
 ('052_namespace_unused',to_regclass('public.finance_tax_filings') is null and to_regclass('public.finance_tax_filing_allocations') is null and to_regclass('public.finance_tax_filing_audit') is null and to_regclass('public.finance_tax_remittances') is null and to_regclass('public.finance_tax_remittance_audit') is null
 and not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and (proname like 'tax_filing_%' or proname in('tax_filing_can_manage','tax_filing_can_remit','tax_filing_pool','tax_filing_immutable','tax_filing_assert','create_finance_tax_filing','transition_finance_tax_filing','tax_filing_account','create_finance_tax_remittance','transition_finance_tax_remittance','tax_filing_remittance_assert','tax_filing_integrity','tax_filing_cash_reversal_guard','get_finance_tax_filings','get_finance_tax_position_before_filing')))
